function CatHouseCatListDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.__EventRequestCompleteAction then
            Events.RemoveListener(EVENT_REQUEST_COMPLETE, self.__EventRequestCompleteAction)
            self.__EventRequestCompleteAction = nil
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function CatHouseCatListDialog:InitData()
    -----------------------------
    ---配表相关
    --- 猫咪列表空位上限
    local catListUpLimit = CatHouseMgr:GetInstance():GetCatListUpLimit()
    --- 喵喵屋主界面可显示猫咪数量
    local maxMainShowNun = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.MaxMainShowNun).num)

    --- 训练次数上限（同时也是进化所需数量）
    local trainTimeLimit = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.TrainTimeLimit).num)

    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = component:GetCatHouseHomeDojo()
    self.catHouseHomeDojo = catHouseHomeDojo

    self.catListUpLimit  = catListUpLimit
    self.maxMainShowNun  = maxMainShowNun
    self.viewType        = ViewType.CatList
    self.trainTimeLimit  = trainTimeLimit
end

function CatHouseCatListDialog:InitCardList()
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = self.catHouseHomeDojo
    
    local curListType = self.curListType
    local checkCondition = function(catData)
        if curListType == ListType.Adult then
            return checkNumber(catData.age) == BornType.Adult
        elseif curListType == ListType.Baby then
            return checkNumber(catData.age) == BornType.Baby
        end
        return true

    end

    local catList = {}
    for i, v in ipairs(catHouseHomeDojo.catList) do
        if checkCondition(v) and checkTable(component:GetCDDataById(v.id))[ConstantsCatHouse.CatStatus.Hatching] == nil then
            table.insert(catList, v)
        end
    end
 
    self.catList = catList

end

function CatHouseCatListDialog:InitTabToggle()
    ---@type CommonTabToggleLeft
    local env = CfUtils.GetLuaScr(self.CommonTabToggleLeft.gameObject, CommonTabToggleLeftPath)
    if isNull(env) then return end
    local togglesData = self:InitToggleData()
    env:FillToggles(togglesData)
end


function CatHouseCatListDialog:InitToggleData()
    local t = {
        [ListType.All]   = { localize("全部") },
        [ListType.Adult] = { localize("成熟期") },
        [ListType.Baby]  = { localize("幼年期") },
    }
    local toggles = {}
    for subType, conf in ipairs(t) do
        local name = SafeUnpack(conf)

        local toggleData = {
            text = name,
            textColor = {
                selected = "#FFFFFF",
                default  = "#2E2E2E"
            },
            lock = false,
            func = function()
                self:OnSelectTabChange(subType)
            end
        }

        table.insert(toggles, toggleData)
    end
    return toggles

end

