function CatHouseCatListDialog:FreshFilterNode()
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBNode)
    if nodeEnv == nil then return end
    nodeEnv:SetFilterClass()
    nodeEnv:SetExtraParams(checkNumber(self.catHouseHomeDojo.partyCatId))
    nodeEnv:SetCallback(self.catList, Bind(self, self.OnClickFilterNode), Constants.UISortType.CatHouse)
    nodeEnv:RestoreState("CatHouseCatListDialog", Bind(self, self.OnClickFilterNode))
end

function CatHouseCatListDialog:FreshListUI()
    local len  = #self.catList
    local isShowList = len > 0
    KTool.SetActive(self.EmptyNode.gameObject, len == 0)
    KTool.SetActive(self.CatList.gameObject, isShowList)
    if not isShowList then
        return
    end
    local List = self.CatList
    if not List.mLoopListView.IsListViewInit then
        List:InitListView(len, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(List, len)
    end
end

function CatHouseCatListDialog:OnGetItemByIndex(cell, index)
    if index < 0 then
        return nil
    end
    
    ---@type CatHouseListBtnNode
    local nodeEnv = CfUtils.GetLuaScr(cell, CellEnvPath)
    if isNull(nodeEnv) then
        return nil
    end
    
    local position         = index + 1
    nodeEnv:SetCallback(Bind(self, self.OnClickCatNodeAction))
    nodeEnv:FreshCommonUI(self.catList[position])
    nodeEnv:FreshCatListUI(self.isShowAttr, self.trainTimeLimit)

    return cell

end

function CatHouseCatListDialog:RequestRallySignup(catData, price)
    local rallyId = self.extraParams.rallyId
    local playerCatId = catData.id
    GameUtils.Request(Interfaces.CatHouseRallySignup, {
        rallyId = rallyId, playerCatId = playerCatId, price = price
    }, function(req, response)
        ------------------------
        --- 1. 处理数据
        --- 1.1 获取登记持续时间
        local remainTime = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallySignupSeconds).num)

        --- 1.2 添加登记数据
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        component:UpdateRallySignupData(rallyId, {
            rallyId = rallyId, playerCatId = playerCatId,
            price = price, remainTime = remainTime, asked = 0
        })

        --- 1.3 添加登记倒计时数据
        component:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Signup, remainTime)

        ------------------------
        ---2. 回到登记界面
        --if self.callback then
        --    self.callback(self.catData)
        --end
        UIModule.BackDialog()

    end)
end

function CatHouseCatListDialog:RequestUnlockCatLimit(consume, number)
    GameUtils.Request(Interfaces.CatHouseUnlockCatLimit, {}, function(req, response)
        GoodsUtils.DrawRewards(consume)

        local maxCatsNum = checkNumber(self.catHouseHomeDojo.maxCatsNum) + number
        self.catHouseHomeDojo:FillFieldData("maxCatsNum", maxCatsNum)

        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        ---@type PlayerDojo
        local playerDojo = playerComponent.playerDojo
        playerDojo.catHouseMaxCatNum = maxCatsNum

        self:FreshQuantityGroup()
        self:FreshAddBtnShowState()
    end)
end

function CatHouseCatListDialog:SwitchListDetail(isShowAttr)
    self.isShowAttr = isShowAttr
    self:FreshListDetailShowState(isShowAttr)
    self:FreshListUI()

end

function CatHouseCatListDialog:FreshListDetailShowState(isShowAttr)
    KTool.SetActive(self.BtnCatDetailsImgSelect.gameObject,   not isShowAttr)
    KTool.SetActive(self.BtnAttributeDetailsImgSelect.gameObject, isShowAttr)
end

