function CatHouseCatListDialog:OnClickBtnAddAction()
    ---@type CatHouseComponent
    local component      = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local expansionTimes = CatHouseMgr:GetInstance():GetCatListExpansionTimes(checkNumber(component:GetCatHouseHomeDojo().maxCatsNum))
    local row            = CfUtils.GetCfLine(AutoIds.IdSetting1914, expansionTimes + 1)
    if row == nil then
        return
    end

    local placeNum = checkNumber(row:Get("placeNum"))
    local goodsId  = checkNumber(row:Get("goods"))
    local goodsNum = checkNumber(row:Get("goodsNum"))

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    GameUtils.SecondConfirm(localize("是否消耗_num_个_name_扩充_num1_个空位？", {_num_ = goodsNum, _name_ = goodsVo.name, _num1_ = placeNum}), function()
        local consume, errTip = GoodsUtils.CheckGoodConsume({ { goodsId = goodsId, goodsNum = goodsNum } })
        if errTip then
            GameUtils.Toast(errTip)
            return
        end
        self:RequestUnlockCatLimit(consume, placeNum)

    end)

end


function CatHouseCatListDialog:OnClickCatNodeAction(catData, targetNode)
    self:HandleClickTypeCatList(catData)

end

function CatHouseCatListDialog:HandleClickTypeCatList(catData)
    ---@type CatHouseComponent
    local component    = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local remainTime   = checkTable(component:GetCDDataById(catData.id))[ConstantsCatHouse.CatStatus.Hatching]
    local isIncubation = remainTime ~= nil
    if isIncubation then
        if remainTime == 0 then
            UIModule.CloseDialog(self.controller)
            UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseCultivationPopup })
        else
            GameUtils.Toast(localize("猫咪还在培育中"))
        end
        return
    end
    --- 进入查看模型界面
    --CatHouseMgr:GetInstance():ShowLookModelDialog(catData, {{id = Constants.UITypeIds.CatHouseCatListDialog}})
    UIModule.OpenDialog({id = Constants.UITypeIds.CatHouseInteractionDialog, parameters = {catId = catData.id, catDataList = self.catList}},
            {{id = Constants.UITypeIds.CatHouseCatListDialog}}
    )
end

