function CatHouseCatListDialog:OnSelectTabChange(listType)
    if self.curListType == listType then return end
    self.curListType = listType
    self:InitCardList()
    self:FreshFilterNode()
    
end

function CatHouseCatListDialog:OnClickBtnCatDetailsAction()
    self:SwitchListDetail(false)

end

function CatHouseCatListDialog:OnClickBtnAttributeDetailsAction()
    self:SwitchListDetail(true)
    
end

function CatHouseCatListDialog:OnClickBtnDisplaySettingAction()
    --- 进入展示列表
    UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseDisplaySettingDialog })
end

function CatHouseCatListDialog:OnEventRequestCompleteAction(code, path)
    if checkNumber(code) ~= 0 then
        return
    end

    if path == Interfaces.CatHouseSetPartyCat then
        self:FreshListUI(self.catList)
    elseif path == Interfaces.CatHouseSetShowCat then
        self:FreshDisplayGroup()
    end

end

